// Builds the Decap CMS config from the slide registry. Slide fields come only
// from each slide module's cmsFields; this file adds the session-level fields
// and the provisional Decap settings that M0-10 verifies against a live portal.
import type { CmsField } from "../../src/slides/cms-field.ts";
import { slideRegistry } from "../../src/slides/registry.ts";
import type { AnySlideModule } from "../../src/slides/types.ts";

export const CONFIG_PATH = "public/admin/config.yml";

const HEADER = [
  "# Generated by `npm run cms:generate` from the slide registry. Do not edit by hand.",
  "# CI runs `npm run cms:check` and fails if this file is out of date.",
  "# The body is JSON, which is also valid YAML.",
];

const SLIDE_BASE_FIELDS: readonly CmsField[] = [
  {
    name: "id",
    label: "Slide id",
    widget: "string",
    hint: "A short name for this slide, such as landmark-1. Use lowercase letters, digits and hyphens. Keep it the same after the slide is published.",
    pattern: [
      "^[a-z0-9]+(?:-[a-z0-9]+)*$",
      "Use lowercase letters, digits and single hyphens",
    ],
  },
  {
    name: "notes",
    label: "Facilitator notes",
    widget: "text",
    required: false,
    hint: "Shown to the facilitator only, never to the group.",
  },
];

const SESSION_FIELDS: readonly CmsField[] = [
  {
    name: "slug",
    label: "Web address name",
    widget: "string",
    hint: "Used in the session's web address. Must match the file name.",
    pattern: [
      "^[a-z0-9]+(?:-[a-z0-9]+)*$",
      "Use lowercase letters, digits and single hyphens",
    ],
  },
  {
    name: "number",
    label: "Session number",
    widget: "number",
    value_type: "int",
    min: 1,
    max: 14,
  },
  { name: "title", label: "Session title", widget: "string" },
];

function slideType(module: AnySlideModule) {
  return {
    name: module.type,
    label: module.label,
    widget: "object",
    fields: [...SLIDE_BASE_FIELDS, ...module.cmsFields],
  };
}

export function buildCmsConfig(
  modules: readonly AnySlideModule[] = slideRegistry.modules,
) {
  return {
    backend: { name: "github", repo: "oss-slu/gwep-cst", branch: "main" },
    local_backend: true,
    publish_mode: "editorial_workflow",
    media_folder: "public/media",
    public_folder: "/media",
    collections: [
      {
        name: "sessions",
        label: "Sessions",
        label_singular: "Session",
        folder: "content/sessions",
        extension: "json",
        format: "json",
        create: false,
        delete: false,
        identifier_field: "title",
        slug: "{{fields.slug}}",
        // Uploads go into the session's own folder, public/media/<slug>/,
        // and are referenced as /media/<slug>/<file>: the path rule that
        // validate-content and validate-media enforce.
        media_folder: "/public/media/{{slug}}",
        public_folder: "/media/{{slug}}",
        fields: [
          ...SESSION_FIELDS,
          {
            name: "slides",
            label: "Slides",
            widget: "list",
            typeKey: "type",
            types: modules.map(slideType),
          },
        ],
      },
    ],
  };
}

/**
 * The exact file contents. JSON.stringify escapes every label and hint, and the
 * output depends only on the registry order, so it is identical on every run.
 */
export function serializeCmsConfig(
  config: ReturnType<typeof buildCmsConfig>,
): string {
  return `${HEADER.join("\n")}\n${JSON.stringify(config, null, 2)}\n`;
}
